python -c "import csv, warnings; from pymatgen.core import Structure; from pymatgen.symmetry.analyzer import SpacegroupAnalyzer; warnings.filterwarnings('ignore'); rows=list(csv.DictReader(open('nlo_pool.csv'))); print('Candidates:',len(rows));
for r in rows:
 s=Structure.from_str(r['poscar'],fmt='poscar'); groups=[]
 for tol in [0.001,0.01,0.1]:
  a=SpacegroupAnalyzer(s,symprec=tol); groups.append(f'{a.get_space_group_symbol()}({a.get_space_group_number()})/{a.get_point_group_symbol()}')
 print(r['candidate_id'],s.composition.reduced_formula,len(s),f'V/atom={s.volume/len(s):.2f}',' | '.join(groups))"

python -c "import csv,warnings,numpy as np; from pymatgen.core import Structure; warnings.filterwarnings('ignore'); rows=list(csv.DictReader(open('nlo_pool.csv')));
for r in rows:
 cid=r['candidate_id']; num=int(cid[1:])
 if not (num<=19 or 31<=num<=36 or 94<=num<=99): continue
 s=Structure.from_str(r['poscar'],fmt='poscar'); print(cid,s.composition.reduced_formula,'V',round(s.volume,1))
 for el in ['Ga','Zn','Mg']:
  tensors=[]; dists=[]; coords=[]
  for site in s:
   if site.specie.symbol!=el: continue
   nn=sorted([n for n in s.get_neighbors(site,4) if n.specie.symbol=='Se'],key=lambda n:n.nn_distance); near=[n for n in nn if n.nn_distance<min(nn[0].nn_distance*1.25,3.2)] if nn else []
   if not near: continue
   u=np.array([(n.coords-site.coords)/n.nn_distance for n in near]); tensors.append(np.einsum('bi,bj,bk->ijk',u,u,u)); dists.extend(n.nn_distance for n in near); coords.append(len(near))
  if tensors:
   T=np.array(tensors); G=T.sum(axis=0); print(el,'CN',coords,'bonds',round(min(dists),3),round(max(dists),3),'coherence',round(np.linalg.norm(G)/sum(np.linalg.norm(t) for t in T),3),'max/V',round(np.max(np.abs(G))/s.volume*1000,3),'norm/V',round(np.linalg.norm(G)/s.volume*1000,3))"

python -c "import csv,warnings,numpy as np; from pymatgen.core import Structure; from pymatgen.symmetry.analyzer import SpacegroupAnalyzer; warnings.filterwarnings('ignore'); targets={'c030':{'Cd':'P','Si':'P'},'c037':{'Be':'Se'},'c038':{'Sb':'S'},'c041':{'B':'S'},'c055':{'Al':'As','Ga':'As'},'c057':{'Al':'S'},'c081':{'Al':'S','Zn':'S'}};
for r in csv.DictReader(open('nlo_pool.csv')):
 cid=r['candidate_id']
 if cid not in targets: continue
 s=Structure.from_str(r['poscar'],fmt='poscar'); a=SpacegroupAnalyzer(s,symprec=.01); print(cid,s.composition.reduced_formula,a.get_space_group_symbol(),a.get_point_group_symbol())
 for el,ligand in targets[cid].items():
  ts=[]; ds=[]; angles=[]
  for site in s:
   if site.specie.symbol!=el: continue
   nn=sorted([n for n in s.get_neighbors(site,3.5) if n.specie.symbol==ligand],key=lambda n:n.nn_distance)[:(3 if el in ['B','Sb'] else 4)]; u=np.array([(n.coords-site.coords)/n.nn_distance for n in nn]); ts.append(np.einsum('bi,bj,bk->ijk',u,u,u)); ds.extend(n.nn_distance for n in nn); angles.extend(np.degrees(np.arccos(np.clip(np.dot(u[i],u[j]),-1,1))) for i in range(len(u)) for j in range(i+1,len(u)))
  total=np.sum(ts,axis=0); print(' ',el+'-'+ligand,'units',len(ts),'distance',round(min(ds),3),round(max(ds),3),'angle',round(min(angles),2),round(max(angles),2),'geometric retention',round(np.linalg.norm(total)/sum(np.linalg.norm(t) for t in ts),3))"

